-- Restore referenced gameobject parents removed by the former entry-zero cleanup.
-- Source: TBCDB 1.11.0 seed plus the corresponding committed instance updates.
-- Existing GUIDs are preserved; native pool/event/spawn-group selection remains intact.
CREATE TEMPORARY TABLE logfix_spawn_stage LIKE gameobject;
SELECT s.`guid`,s.`id`,s.`map`,s.`spawnMask`,s.`position_x`,s.`position_y`,s.`position_z`,s.`orientation`,s.`rotation0`,s.`rotation1`,s.`rotation2`,s.`rotation3`,s.`spawntimesecsmin`,s.`spawntimesecsmax` FROM logfix_spawn_stage s LEFT JOIN gameobject g ON g.guid=s.guid WHERE g.guid IS NULL;
DROP TEMPORARY TABLE logfix_spawn_stage;
